# --- Clock 주입 ---

@Configuration
public class ClockConfig {
    @Bean
    public Clock clock() {
        return Clock.systemDefaultZone();
    }
}

@Service
@RequiredArgsConstructor
public class OrderService {
    private final Clock clock;

    @Transactional
    public OrderResponse createOrder(OrderCreateRequest request) {
        LocalDateTime now = LocalDateTime.now(clock);
        ...
    }
}

#   테스트에서 고정한다

@TestConfiguration
static class FixedClockConfig {
    @Bean
    @Primary
    Clock fixedClock() {
        return Clock.fixed(
                LocalDateTime.of(2026, 9, 9, 11, 0)
                        .atZone(ZoneId.systemDefault()).toInstant(),
                ZoneId.systemDefault());
    }
}

@SpringBootTest
@Import(FixedClockConfig.class)
class OrderServiceClockTest extends IntegrationTestSupport {

    @DisplayName("주문 등록 시각이 고정된 시각으로 기록된다")
    @Test
    void createOrder() {
        productRepository.save(createProduct("001", 4000));

        OrderResponse response = orderService.createOrder(request);

        assertThat(response.getRegisteredDateTime())
                .isEqualTo(LocalDateTime.of(2026, 9, 9, 11, 0));
    }
}

$ ./gradlew test --tests OrderServiceClockTest

