public interface OrderNumberGenerator {
    String generate();
}

@TestConfiguration
static class FixedNumberConfig {
    @Bean @Primary
    OrderNumberGenerator fixedGenerator() {
        return () -> "ORD-20260909-0001";
    }
}

@Test
void createOrderWithNumber() {
    productRepository.save(createProduct("001", 4000));

    OrderResponse response = orderService.createOrder(request);

    assertThat(response.getOrderNumber()).isEqualTo("ORD-20260909-0001");
}

$ ./gradlew test --tests OrderServiceClockTest

OrderServiceClockTest > createOrderWithNumber() PASSED

#   값이 정해졌다

# --- 성질만 검증하면 ---

@DisplayName("주문 번호는 천 번을 뽑아도 겹치지 않는다")
@Test
void orderNumberIsUnique() {
    OrderNumberGenerator generator = new UuidOrderNumberGenerator();

    Set<String> numbers = IntStream.range(0, 1000)
            .mapToObj(i -> generator.generate())
            .collect(toSet());

    assertThat(numbers).hasSize(1000);
}

$ ./gradlew test --tests OrderNumberGeneratorTest

OrderNumberGeneratorTest > 주문 번호는 천 번을 뽑아도 겹치지 않는다 PASSED

BUILD SUCCESSFUL in 1s

#   값은 안 본다. 안 겹친다만 본다

#   2.6절에서 isNotNull() 로 갔던 자리다

# --- 생성기를 망가뜨리면 ---

public String generate() {
    return "ORD-" + LocalDate.now();      // 날짜만
}

$ ./gradlew test --tests OrderNumberGeneratorTest

OrderNumberGeneratorTest > 주문 번호는 천 번을 뽑아도 겹치지 않는다 FAILED
    Expected size: 1000 but was: 1

#   잡는다

#   값을 모르는데도 검증했다

# --- 시드를 고정하면 ---

@Test
void seededRandom() {
    Random random = new Random(42);

    assertThat(random.nextInt(100)).isEqualTo(63);
    assertThat(random.nextInt(100)).isEqualTo(11);
}

$ ./gradlew test --tests RandomTest

RandomTest > seededRandom() PASSED

$ ./gradlew test --tests RandomTest --rerun-tasks

RandomTest > seededRandom() PASSED

#   같은 시드면 같은 값이다

#   그런데 이 63 과 11 은 JDK 구현에 달렸다

#   JDK 를 바꾸면

RandomTest > seededRandom() FAILED
    expected: 63 but was: 88

#   (실제로는 java.util.Random 이 스펙에 고정돼 있어 잘 안 바뀌는데,
#    ThreadLocalRandom 이나 SecureRandom 은 다르다)

#   구현 값을 단언하는 건 위험하다

# --- 세 방법 정리 ---

#   값 전달        가장 단순. 호출자가 만든다
